// 检查点保存全部计划、复评和公平游标；读取绝不重选策略或重抽随机。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "director_model.hpp"
#include "resident/storage/common_checkpoint.hpp"
namespace hanmo::resident {
namespace {
Status visit_subject(CodecVisitor& c,SubjectRef& s){Integer kind=static_cast<Integer>(s.kind);c.field("kind",kind);if(kind<0||kind>2)return c.reject("InvalidDirectorSubject");if(c.reading())s.kind=static_cast<SubjectKind>(kind);return c.field("id",s.id);}
}
Status visit_director_checkpoint(CodecVisitor& c,DirectorState& s,bool regional_life,bool named_membership,bool dynamic_subjects){
if(c.reading())s.dynamic_subjects=dynamic_subjects;else if(s.dynamic_subjects!=dynamic_subjects)return c.reject("DirectorRegistryVersionMismatch");
if(dynamic_subjects){
    Integer version=1;c.field("registry_version",version);if(version!=1)return c.reject("UnsupportedDirectorRegistryVersion");
    auto registrations=common_checkpoint::table(c,"registrations",s.registrations,[](CodecVisitor& v,DirectorRegistration& r){
        v.field("actor_id",r.actor_id);v.field("policy_id",r.policy_id);v.field("admission_id",r.admission_id);v.field("reason",r.reason);v.field("epoch",r.epoch);v.field("entered_tick",r.entered_tick);v.field("changed_tick",r.changed_tick);
        Integer lifecycle=static_cast<Integer>(r.lifecycle);v.field("lifecycle",lifecycle);if(lifecycle<0||lifecycle>2)return v.reject("InvalidDirectorLifecycle");if(v.reading())r.lifecycle=static_cast<DirectorLifecycle>(lifecycle);
        return v.field("obligations_only",r.obligations_only);
    });if(!registrations.ok)return registrations;
}else if(!s.registrations.empty())return c.reject("DirectorRegistryCapabilityRequired");
if(c.reading())s.named_membership=named_membership;else if(s.named_membership!=named_membership)return c.reject("DirectorMembershipVersionMismatch");if(named_membership){Integer version=1;c.field("named_membership_version",version);if(version!=1)return c.reject("UnsupportedDirectorMembershipVersion");}if(c.reading())s.regional_life=regional_life;else if(s.regional_life!=regional_life)return c.reject("DirectorVersionMismatch");if(!regional_life&&!c.reading())for(const auto& row:s.plans.rows())if(row.second.livelihood||row.second.pending_life_action_id||row.second.last_life_fact_id||row.second.template_id=="private_livelihood")return c.reject("RegionalLifeCapabilityRequired");c.field("fairness_cursor",s.fairness_cursor);c.field("last_boundary_tick",s.last_boundary_tick);common_checkpoint::table(c,"schedules",s.schedules,[](CodecVisitor& v,ReviewSchedule& r){v.object("subject",[&](CodecVisitor& x){return visit_subject(x,r.subject);});v.field("next_tick",r.next_tick);v.field("decision_seq",r.decision_seq);v.field("waiting_since",r.waiting_since);v.field("last_decision_tick",r.last_decision_tick);common_checkpoint::strings(v,"wake_reasons",r.wake_reasons);return v.field("last_outcome",r.last_outcome);});auto visit_plan=[regional_life,dynamic_subjects](CodecVisitor& v,FinitePlan& p){if(dynamic_subjects)v.field("policy_id",p.policy_id);v.field("id",p.id);v.field("template_id",p.template_id);v.field("goal_ref",p.goal_ref);v.object("subject",[&](CodecVisitor& x){return visit_subject(x,p.subject);});v.field("step_index",p.step_index);v.field("next_review_tick",p.next_review_tick);Integer phase=static_cast<Integer>(p.phase);v.field("phase",phase);if(phase<0||phase>7)return v.reject("InvalidDirectorPhase");if(v.reading())p.phase=static_cast<PlanPhase>(phase);v.field("retry_reason",p.retry_reason);v.optional("current_action_id",p.current_action_id,[](CodecVisitor& x,StableId& id){return x.field("value",id);});v.optional("org_activity_id",p.org_activity_id,[](CodecVisitor& x,StableId& id){return x.field("value",id);});common_checkpoint::strings(v,"commitment_ids",p.commitment_ids);common_checkpoint::strings(v,"known_report_ids",p.known_report_ids);if(regional_life){v.optional("livelihood",p.livelihood,[](CodecVisitor& x,LivelihoodIntent& i){x.field("goal_id",i.goal_id);x.field("item_id",i.item_id);x.field("target_quantity",i.target_quantity);x.field("selected_service_role_id",i.selected_service_role_id);x.field("selected_shop_id",i.selected_shop_id);x.field("selected_source_id",i.selected_source_id);x.field("selected_tick",i.selected_tick);return x.field("return_place_id",i.return_place_id);});v.optional("pending_life_action_id",p.pending_life_action_id,[](CodecVisitor& x,StableId& id){return x.field("value",id);});v.optional("last_life_fact_id",p.last_life_fact_id,[](CodecVisitor& x,StableId& id){return x.field("value",id);});}return common_success();};auto plans=common_checkpoint::table(c,"plans",s.plans,visit_plan);if(!plans.ok)return plans;if(dynamic_subjects)return common_checkpoint::table(c,"archived_plans",s.archived_plans,visit_plan);return plans;}
} // 外层完整候选验证后才能发布；单域字节成功不等于世界可运行。
